.pmpr-card:hover .pmpr-in,.pmpr-card:focus-within .pmpr-in{rotate:calc(var(--r1)*-1);translate:0 -12px;box-shadow:0 2px 0 color-mix(in srgb,var(--pm-ink) 8%,transparent),0 54px 80px -40px rgba(0,0,0,.75)}
.pmpr-hd{display:flex;flex-direction:column;gap:10px;margin:0 -28px;padding:20px 28px 18px;border-bottom:1.5px solid var(--pm-ink);background:repeating-linear-gradient(45deg,color-mix(in srgb,var(--pm-ink) 6%,transparent) 0 1px,transparent 1px 7px);border-radius:20px 20px 0 0;box-shadow:inset 0 -4px 0 -2.5px var(--pm-bone),inset 0 -5px 0 -2.5px color-mix(in srgb,var(--pm-ink) 30%,transparent)}
.pmpr-no{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--pm-mut)} .pmpr-name{margin:0;font-size:clamp(28px,2.3vw,34px);line-height:1;letter-spacing:-.02em;font-weight:400}
.pmpr-price{display:flex;align-items:flex-end;gap:12px;margin-top:22px} .pmpr-card.is-feat .pmpr-price{gap:30px}
.pmpr-amt{position:relative;display:inline-flex;font-size:64px;line-height:1.15;letter-spacing:-.03em;padding:0 4px}
.pmpr-roll{display:inline-flex} .pmpr-dg{position:relative;display:inline-block;height:1.15em;overflow:hidden} .pmpr-gh{visibility:hidden;display:block;line-height:1.15em} .pmpr-strip{position:absolute;left:0;top:0;display:flex;flex-direction:column;transition:transform .8s cubic-bezier(.65,0,.25,1)} .pmpr-strip span{display:block;height:1.15em;line-height:1.15em;text-align:center}
.pmpr-dg:nth-last-child(2) .pmpr-strip{transition-delay:.06s} .pmpr-dg:nth-last-child(3) .pmpr-strip{transition-delay:.12s}
.pmpr-ring{position:absolute;left:-16%;top:-14%;width:130%;height:128%;overflow:visible;pointer-events:none} .pmpr-ring path{fill:none;stroke:var(--pm-brass);stroke-width:3.4;stroke-linecap:round;stroke-dasharray:1.02;stroke-dashoffset:calc(1.02 - 1.02*clamp(0,(var(--t) - .05)/.55,1))}
.pmpr-note{display:flex;flex-direction:column;gap:4px;padding-bottom:8px;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--pm-mut)} .pmpr-note em{font-style:normal;opacity:0;translate:0 4px;transition:opacity .4s,translate .4s} .pmpr-note em.is-on{opacity:1;translate:0 0}
.pmpr-tl{margin:18px 0 0;font-size:16px;line-height:1.5;color:color-mix(in srgb,var(--pm-ink) 82%,var(--pm-bone));min-height:3em}
.pmpr-thumbs{display:flex;align-items:center;gap:12px;margin-top:16px} .pmpr-tw{display:flex} .pmpr-th{position:relative;width:42px;height:42px;border-radius:50%;overflow:hidden;margin-left:-10px;box-shadow:0 0 0 2.5px var(--pm-bone);background:var(--pm-fog)} .pmpr-th:first-child{margin-left:0}
.pmpr-th img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover} .pmpr-thb{filter:grayscale(1) contrast(1.15) brightness(1.18)} .pmpr-thc{clip-path:circle(0% at 50% 100%);transition:clip-path .7s cubic-bezier(.65,0,.25,1) calc(var(--q)*.08s)}
.pmpr-card:hover .pmpr-thc,.pmpr-card:focus-within .pmpr-thc,.pmpr.is-fin .pmpr-thc{clip-path:circle(75% at 50% 100%)} .pmpr-tc{font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--pm-mut)}
