.pmpr-tk{width:20px;height:20px;flex:none;margin-top:-1px;overflow:visible} .pmpr-tk path{fill:none;stroke:var(--pm-brass);stroke-width:3.2;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1.02;stroke-dashoffset:calc(1.02 - 1.02*clamp(0,(var(--t) - var(--j)*.13)/.22,1))}
.pmpr-cta .pm-btn{width:100%} .pmpr-cta .pm-face{justify-content:flex-start}
.pmpr-card.is-feat .pmpr-in{padding-bottom:32px;box-shadow:0 0 0 2px var(--pm-brass),0 40px 70px -40px rgba(0,0,0,.65)} .pmpr-card.is-feat .pmpr-hd{padding-top:30px} .pmpr-card.is-feat .pmpr-amt{font-size:72px}
