.pmpr-foot{display:flex;flex-wrap:wrap;justify-content:center;gap:10px 0;margin-top:clamp(48px,4.4vw,68px);font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:color-mix(in srgb,var(--pm-cloud) 78%,var(--pm-pine))} .pmpr-foot span{display:inline-flex;align-items:center} .pmpr-foot i{width:6px;height:6px;margin:0 16px;border-radius:50%;background:var(--pm-brass)}
.pmpr.is-fin .pmpr-card{--k:1;--t:1}
.pmpr.is-tab .pm-wrap{--pad:40px} .pmpr.is-tab .pmpr-top{grid-template-columns:1fr;gap:30px}
.pmpr.is-tab .pmpr-grid,.pmpr.is-ph .pmpr-grid{grid-template-columns:1fr;gap:44px} .pmpr.is-tab .pmpr-card,.pmpr.is-ph .pmpr-card{translate:0 calc((1 - var(--k))*min(26vh,220px))}
.pmpr.is-tab .pmpr-in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);column-gap:36px;align-items:start} .pmpr.is-tab .pmpr-hd{grid-column:1/-1} .pmpr.is-tab .pmpr-price,.pmpr.is-tab .pmpr-tl,.pmpr.is-tab .pmpr-thumbs,.pmpr.is-tab .pmpr-cta{grid-column:1} .pmpr.is-tab .pmpr-inc{grid-column:2;grid-row:2/span 5;margin-top:26px} .pmpr.is-tab .pmpr-cta{margin-top:22px}
.pmpr.is-ph{padding:84px 0 84px} .pmpr.is-ph .pm-wrap{--pad:16px} .pmpr.is-ph .pmpr-top{grid-template-columns:1fr;gap:28px} .pmpr.is-ph .pmpr-sw{flex-wrap:wrap}
.pmpr.is-ph .pmpr-in{padding:0 20px 22px} .pmpr.is-ph .pmpr-hd{margin:0 -20px;padding:18px 20px 16px} .pmpr.is-ph .pmpr-card.is-feat .pmpr-hd{padding-top:28px} .pmpr.is-ph .pmpr-amt{font-size:56px} .pmpr.is-ph .pmpr-card.is-feat .pmpr-amt{font-size:60px} .pmpr.is-ph .pmpr-tl{min-height:0}
.pmpr.is-ph .pmpr-foot{justify-content:flex-start;flex-direction:column;gap:10px} .pmpr.is-ph .pmpr-foot i{margin:0 10px 0 0} .pmpr.is-ph .pmpr-foot span:not(:first-child)::before{content:none}
@media (prefers-reduced-motion:reduce){.pmpr-card{--k:1!important;--t:1!important} .pmpr-hi{transform:none!important} .pmpr-pen path{stroke-dashoffset:0!important}}

