.pmpr-h{margin:0;font-size:clamp(40px,4.3vw,64px);line-height:.98;letter-spacing:-.02em;font-weight:400;text-wrap:balance}
.pmpr-hl{display:block;overflow:hidden;padding-bottom:.16em;margin-bottom:-.16em} .pmpr-hi{display:block;transform:translateY(105%);transition:transform 1.1s cubic-bezier(.2,.8,.2,1)} .pmpr-h.is-on .pmpr-hi{transform:none}
.pmpr-em{position:relative;display:inline-block;white-space:nowrap} .pmpr-pen{position:absolute;left:-2%;width:104%;bottom:-.07em;height:.22em;overflow:visible} .pmpr-pen path{fill:none;stroke:var(--pm-brass);stroke-width:5;stroke-linecap:round;stroke-dasharray:340;stroke-dashoffset:340;transition:stroke-dashoffset 1s cubic-bezier(.65,0,.25,1) .75s} .pmpr-h.is-on .pmpr-pen path{stroke-dashoffset:0}
/* local fix for the shared Btn (kit bug): the hover fill was positioned on the label and painted over its text; fill the whole face, under the label */ .pmpr .pm-lbl{position:static;z-index:auto} .pmpr .pm-hl{z-index:-1}
.pmpr{background:var(--pm-pine);color:var(--pm-cloud);padding:clamp(96px,10vw,150px) 0 clamp(90px,9vw,130px);overflow:clip}
.pmpr::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.5;background-image:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'200'%20height%3D'200'%3E%3Cfilter%20id%3D'n'%3E%3CfeTurbulence%20type%3D'fractalNoise'%20baseFrequency%3D'.7'%20numOctaves%3D'2'%20stitchTiles%3D'stitch'%2F%3E%3CfeColorMatrix%20values%3D'0%200%200%200%201%200%200%200%200%201%200%200%200%200%201%200%200%200%201.6%20-.95'%2F%3E%3C%2Ffilter%3E%3Crect%20width%3D'100%25'%20height%3D'100%25'%20filter%3D'url(%23n)'%2F%3E%3C%2Fsvg%3E");mix-blend-mode:normal}
.pmpr-top{position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:40px}
.pmpr-copy{display:flex;flex-direction:column;gap:22px} .pmpr-sub{margin:0;max-width:520px;font-size:17px;line-height:1.55;color:color-mix(in srgb,var(--pm-cloud) 80%,var(--pm-pine))}
.pmpr-sw{position:relative;display:flex;align-items:center;gap:14px;padding-bottom:8px}
.pmpr-swl{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:color-mix(in srgb,var(--pm-cloud) 62%,var(--pm-pine));cursor:pointer;transition:color .3s;user-select:none} .pmpr-swl.is-on{color:var(--pm-cloud)}
.pmpr-tg{position:relative;width:64px;height:34px;flex:none;border:0;padding:0;border-radius:999px;background:color-mix(in srgb,var(--pm-cloud) 16%,transparent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--pm-cloud) 28%,transparent);cursor:pointer;transition:background .35s}
.pmpr-tg.is-yr{background:var(--pm-brass)} .pmpr-knob{position:absolute;top:4px;left:4px;width:26px;height:26px;border-radius:50%;background:var(--pm-bone);box-shadow:0 3px 8px -2px rgba(0,0,0,.4);transition:translate .45s cubic-bezier(.34,1.56,.64,1)} .pmpr-tg.is-yr .pmpr-knob{translate:30px 0}
.pmpr-save{position:relative;padding:6px 10px;border-radius:12px;background:var(--pm-bone);color:var(--pm-ink);font-size:11px;letter-spacing:.06em;text-transform:uppercase;rotate:-3deg;transition:rotate .5s cubic-bezier(.34,1.56,.64,1),opacity .4s;opacity:.72} .pmpr-save.is-on{opacity:1;rotate:2deg}
.pmpr-save svg{position:absolute;right:calc(100% + 2px);top:-16px;width:40px;height:22px;overflow:visible;rotate:-8deg} .pmpr-save path{fill:none;stroke:var(--pm-brass);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.pmpr-grid{position:relative;display:grid;grid-template-columns:repeat(var(--n),minmax(0,1fr));gap:clamp(20px,2.2vw,34px);align-items:end;margin-top:clamp(56px,5.4vw,84px)}
/* the scroll mechanic: k = this card's progress through its own window */
.pmpr-card
